import hashlib,importlib.util,json,sys
from pathlib import Path
root=Path('/var/projects/toy_physics-s9b-r2-py')
scripts=root/'research/pde_ledger_v3/scripts'
sys.path.insert(0,str(scripts))
import S9b_light_bending_sympy_audit as engine
import S9b_light_bending_sympy_ablation as harness
import sympy as sp
from sympy.core.symbol import Str
from sympy.core.function import AppliedUndef
state=root/'_scratch/s9b-repair-amend6/verified'
basepath=root/'_scratch/s11c/s9b-amend6-verified-baseline/stdout'
print('VALIDATION_WORK baseline parse',file=sys.stderr,flush=True)
baseline=harness.parse(basepath)
shared=sorted(tag for tag in baseline if tag.startswith('PY_S9B_'))
assert set(shared)=={'PY_S9B_'+name for name in engine.SHARED}
failures=[]
eliminations={
 'PY_S9B_R_FLOW_ONLY_':{'s9b_delta','s9b_xi'},
 'PY_S9B_R_SPEED_ONLY_':{'s9b_V','s9b_xi'},
 'PY_S9B_R_TILT_ONLY_':{'s9b_delta','s9b_V'},
 'PY_S9B_R_BULK_ONLY_':{'s9b_V','s9b_xi','s9b_delta'},
 'PY_S9B_F_FLOW_':{'s9b_delta','s9b_xi','s9b_V'},
 'PY_S9B_F_LIVE_':{'s9b_V'},
 'PY_S9B_C_':{'s9b_delta'},
}
for tag,value in baseline.items():
    print('VALIDATION_WORK '+tag,file=sys.stderr,flush=True)
    if not tag.startswith('PY_S9B_'): continue
    if value.has(sp.nan,sp.zoo): failures.append([tag,'nonfinite CAS artifact'])
    checked=value.replace(lambda a:isinstance(a,sp.Equality) and isinstance(a.lhs,AppliedUndef) and a.rhs==0, lambda a:sp.true)
    funcs={node.func.__name__ for node in checked.atoms(AppliedUndef)}
    for prefix,forbidden in eliminations.items():
        if tag.startswith(prefix) and funcs&forbidden:
            failures.append([tag,'unsubstituted profile',sorted(funcs&forbidden)])
    if '_CONDITION_' in tag:
        identity=value[-1]
        if identity.has(sp.Integral,sp.ConditionSet): failures.append([tag,'unreduced matching identity'])
local=sorted(set(baseline)-set(shared))
declared={str(name) for name in baseline['PY_LOCAL_S9B_LOCAL_NAMES']}
assert declared==set(local)
import S9b_exports as exports
for name,digest in exports.BUILD_INPUT_DIGESTS.items():
    assert hashlib.sha256((scripts.parent/name).read_bytes()).hexdigest()==digest
assert isinstance(exports.LEDGER,type(__import__('types').MappingProxyType({})))
knives={}
for knife in harness.KNIVES:
    if knife=='K11': continue
    path=state/'k1-k10'/knife/'run/stdout'
    print('VALIDATION_WORK '+knife+': parse and payload roles',file=sys.stderr,flush=True)
    parsed=harness.parse(path)
    assert set(parsed)==set(baseline)
    changed=[tag for tag in baseline if parsed[tag]!=baseline[tag]]
    value_changes=[]
    domain_changes=[]
    attached=[]
    for tag in baseline:
        left,left_domains=harness.payload_roles(baseline[tag])
        right,right_domains=harness.payload_roles(parsed[tag])
        if left!=right:value_changes.append(tag)
        if left_domains!=right_domains:domain_changes.append(tag)
        if left_domains or right_domains:attached.append(tag)

    before,after=harness.KNIVES[knife]
    line=next(i for i,l in enumerate(engine.HERE.read_text().splitlines(),1) if before in l)
    knives[knife]={'site_line':line,'before':before,'after':after,'changed_payload_tags':changed,'structural_value_projection_changes':value_changes,'structural_domain_projection_changes':domain_changes,'tags_with_attached_domains':attached,
                   'not_established_tags':[tag for tag,value in parsed.items() if "NOT_ESTABLISHED" in harness.render(value)]}
# Mechanical emission coverage: every worker tag has a baseline/corrupted/difference row.
harness_path=root/'_scratch/s11c/s9b-amend6-verified-k1-k10/stdout'
emitted=[]
with harness_path.open() as stream:
    for line in stream:
        emitted.append(line.partition(': ')[0])
        if not emitted[-1].endswith('_CONSTRUCTION'):
            assert "Tuple(Str('VALUE_DIFFERENCE')," in line
            assert "Tuple(Str('DOMAIN_DIFFERENCE')," in line

expected={'PY_LOCAL_S9B_ABLATION_'+knife+'_'+tag for knife in knives for tag in baseline}
expected.update('PY_LOCAL_S9B_ABLATION_'+knife+'_CONSTRUCTION' for knife in knives)
assert set(emitted)==expected and len(emitted)==len(expected)
receipt=json.loads((state/'k11/K11/compact-receipt.json').read_text())
assert set(receipt['evaluated_tags']).isdisjoint(receipt['not_evaluated_tags'])
assert set(receipt['evaluated_tags'])|set(receipt['not_evaluated_tags'])==set(baseline)

namespace={'__builtins__':{},**vars(sp),'Str':Str,'ExprCondPair':harness.ExprCondPair,**harness.RELATIONALS}
k11_rows={}
k11out=root/'_scratch/s11c/s9b-amend6-verified-k11/stdout'
for line in k11out.read_text().splitlines():
    tag,_,payload=line.partition(': ')
    for reached in receipt['evaluated_tags']:
        if tag=='PY_LOCAL_S9B_ABLATION_K11_'+reached:
            value=eval(payload,namespace)
            k11_rows[reached]={'unmutated':harness.render(value[1]),'mutated':harness.render(value[2]),
                'difference':harness.render(value[3]),'method_residual':harness.render(value[4])}
print('VALIDATION_WORK gamma strata and implied exchange',file=sys.stderr,flush=True)
amendment6={}
GM=sp.Symbol('GM',real=True)
for tag,payload in baseline.items():
    if not tag.startswith('PY_S9B_') or '_B_GAMMA_' not in tag:continue
    inside=payload[0][1]
    cases=inside[-1]
    rows=[]
    for domain,solutions in cases:
        assert domain[0]==Str('ATTACHED_DOMAIN')
        zero_domain=domain[1].subs(GM,0)
        rows.append({'domain':harness.render(domain[1]),'solution_set':harness.render(solutions),
                     'domain_at_GM_zero':harness.render(zero_domain)})
    amendment6[tag]={'outer_branch_domain':harness.render(payload[0][0]),
       'outside_branch_domain':harness.render(payload[1][0]),
       'outer_domain_contains_GM':payload[0][0].has(GM),
       'relation_and_solution_sets':harness.render(inside),'cases':rows}
    assert payload[1][1]==Str('NOT_ESTABLISHED')
    assert not inside.has(Str('NOT_ESTABLISHED'))
amendment5={}

for tag,value in baseline.items():
    if tag.endswith('GAMMA_DIFFERENCE'):
        amendment5[tag]={'reduced_value':harness.render(value[0][1])}
    if '_IMPLIED_JN_' in tag:
        if len(value)==3:
            rows=value[1]
            info=dict(value[2])
            kind=str(info[Str('kind')])
            if kind!='UNDETERMINED':
                unevaluated=[i for i,row in enumerate(rows) if row[-1].rhs.has(engine.Velocity)]
                if unevaluated: failures.append([tag,'free velocity in implied exchange',unevaluated])
                amendment5[tag]={'solution_kind':kind,'branches':len(rows),
                    'velocity_solution':harness.render(value[2]),
                    'ode_residual':harness.render(info.get(Str('residual'),sp.EmptySet)),
                    'implied_exchange_rows':harness.render(rows)}
        else:
            amendment5[tag]={'restricted_velocity':harness.render(value[1])}
amendment5['branch_existence']=harness.render(baseline['PY_S9B_BRANCH_EXISTENCE'])
amendment5['branch_types']=harness.render(baseline['PY_S9B_BRANCH_TYPE'])
for response in ('CONSTANT','FIXED_RATIO','POWER'):
    amendment5[response+'_exact_response']=harness.render(baseline['PY_LOCAL_S9B_C_'+response+'_RESPONSE'])
    amendment5[response+'_condition_domain']=harness.render(baseline['PY_S9B_C_'+response+'_CONDITION_DEFLECTION'][3])
summary={'amendment6':amendment6,'amendment5':amendment5,'shared_count':len(shared),'local_count':len(local),'shared_tags':shared,'local_tags':local,
 'missing_shared':[], 'structural_failures':failures,
 'not_established_tags':[tag for tag,value in baseline.items() if "NOT_ESTABLISHED" in harness.render(value)],
 'knives':knives,'K11':receipt|{'evaluations':k11_rows},
 'endpoint_certificates':{tag:harness.render(value) for tag,value in baseline.items() if 'COUNTING_CERTIFICATE' in tag},
 'source_pins':json.loads((state/'source-pins.json').read_text()),
 'runs':json.loads((state/'completion.json').read_text())}
(state/'validation.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps({k:summary[k] for k in ('shared_count','local_count','missing_shared','structural_failures')}),flush=True)
if failures: raise RuntimeError('structural validation failures')
